const upsertStandbyPhoto = `-- name: UpsertStandbyPhoto :one
INSERT INTO standby_photos (standby_id, photo_type, file_id, overlay_text)
VALUES ($1, $2, $3, $4)
ON CONFLICT (standby_id, photo_type) DO UPDATE SET file_id = EXCLUDED.file_id, overlay_text = EXCLUDED.overlay_text
RETURNING id, standby_id, photo_type, file_id, overlay_text, created_at
`

type UpsertStandbyPhotoParams struct {
	StandbyID   uuid.UUID
	PhotoType   string
	FileID      uuid.UUID
	OverlayText *string
}

// One photo per type (customer_worksheet, site_photo): a new file replaces the old one.
func (q *Queries) UpsertStandbyPhoto(ctx context.Context, arg UpsertStandbyPhotoParams) (StandbyPhoto, error) {
	row := q.db.QueryRow(ctx, upsertStandbyPhoto,
		arg.StandbyID,
		arg.PhotoType,
		arg.FileID,
		arg.OverlayText,
	)
	var i StandbyPhoto
	err := row.Scan(
		&i.ID,
		&i.StandbyID,
		&i.PhotoType,
		&i.FileID,
		&i.OverlayText,
		&i.CreatedAt,
	)
	return i, err
}
